package week1.day3;

public class FindOddNumbers {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println("Print odd numbers between 1 to 10");
		for (int i = 1; i < 10; i++) {
			if (i % 2 != 0) {
				System.out.println(i);

			}
		}
	}

}
